using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap a REST API using HttpClient injected via DI.
/// </summary>
[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("List all items from the API. Returns JSON array.")]
    public async Task<string> ListItems(CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Listing all items");
        var items = await httpClient.GetFromJsonAsync<JsonElement>("/items", cancellationToken);
        return JsonSerializer.Serialize(items, JsonOptions);
    }

    [McpServerTool, Description("Get a single item by its unique identifier.")]
    public async Task<string> GetItem(
        [Description("The unique identifier of the item to retrieve")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Getting item {Id}", id);
        var response = await httpClient.GetAsync($"/items/{id}", cancellationToken);

        if (!response.IsSuccessStatusCode)
            return $"Error: item {id} not found (HTTP {(int)response.StatusCode})";

        var item = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(item, JsonOptions);
    }

    [McpServerTool, Description("Create a new item with the given title and body.")]
    public async Task<string> CreateItem(
        [Description("Title for the new item")] string title,
        [Description("Body content for the new item")] string body,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating item: {Title}", title);
        var payload = new { title, body };
        var response = await httpClient.PostAsJsonAsync("/items", payload, cancellationToken);
        response.EnsureSuccessStatusCode();

        var created = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(created, JsonOptions);
    }
}

